from typing import Annotated
from fastapi import Depends

async def get_repository(session: SessionDep) -> OrderRepository:
    return SqlOrderRepository(session)

OrderRepositoryDep = Annotated[OrderRepository, Depends(get_repository)]

@app.get('/orders/{id}')
async def get_order(id: UUID, repository: OrderRepositoryDep):
    return await repository.get(id)

@app.get('/async')
async def async_route(client: HttpClientDep):
    return await client.get_data()       # non-blocking awaitable

@app.get('/blocking-sdk')
def sync_route(client: BlockingClientDep):
    return client.get_data()             # FastAPI thread-pool execution

@router.get('', response_model=Page[OrderRead])
async def list_orders(
    cursor: Annotated[str | None, Query()] = None,
    limit: Annotated[int, Query(ge=1, le=100)] = 50,
    repository: OrderRepositoryDep = ...,
):
    return await repository.page_after(cursor=cursor, limit=limit)

@app.post('/notifications', status_code=202)
async def notify(command: NotificationCreate, tasks: BackgroundTasks):
    record = await repository.create(command)
    tasks.add_task(send_best_effort_metric, record.id)
    await durable_queue.publish(NotificationRequested(record.id))
    return {'id': record.id, 'status': 'queued'}

@app.get('/exports/{id}')
async def download(id: UUID, export: ExportDep):
    path = await export.authorized_path(id)
    return FileResponse(
        path, media_type='text/csv', filename=f'export-{id}.csv',
        headers={'Cache-Control': 'private, no-store'},
    )

@app.delete('/items/{id}', status_code=204)
async def delete_item(id: UUID) -> Response:
    await service.delete(id); return Response(status_code=204)

@app.exception_handler(OrderConflict)
async def order_conflict(request: Request, exc: OrderConflict):
    return JSONResponse(
        status_code=409,
        content={'type': 'order_conflict', 'message': 'Order changed; reload and retry', 'request_id': request.state.request_id},
    )
